namespace CorseVR.Editor {
 public static class TourLittoralLayout {
  const string Root="Assets/Prototype_Maquis/Art/TourLittoral",V2="Assets/Prototype_Maquis/Art/MaquisV2";
  static System.Random rng;static Transform main,tour;static Maquis35Route route;static TourLittoralRoute coast;static MeshCollider originalGround,coastGround;static Vector3[] originalVertices;static Material bot,stone,earth,wood,iron,mortar;static List<GameObject> farObjects=new List<GameObject>();static List<object> placements=new List<object>();
  static float R(float a,float b){return a+(float)rng.NextDouble()*(b-a);}
  static Material AssetMat(string name){return AssetDatabase.LoadAssetAtPath<Material>(V2+"/Materials/"+name+".mat");}
  static Material Lit(string name,Color color,float metallic=0){string p=Root+"/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",metallic>.1f?.30f:.10f);m.SetFloat("_Cull",0);m.doubleSidedGI=true;m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
