  public static string Prepare(){
   foreach(string s in new[]{"Materials","Prefabs","Meshes"})Directory.CreateDirectory(Root+"/"+s);AssetDatabase.Refresh();
   foreach(string file in Directory.GetFiles(Root+"/Models","*.fbx")){var i=AssetImporter.GetAtPath(file.Replace('\\','/')) as ModelImporter;if(i!=null&&!i.isReadable){i.isReadable=true;i.importCameras=false;i.importLights=false;i.SaveAndReimport();}}
   bot=AssetMat("Botanique_Fibres_Nervures");stone=AssetMat("Granit_Quartz_Mica");earth=AssetMat("Terre_Graviers");var ts=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Pierre_Tour_Peinte.mat");if(!ts){ts=new Material(stone);AssetDatabase.CreateAsset(ts,Root+"/Materials/Pierre_Tour_Peinte.mat");}ts.SetColor("_ShadowTint",new Color(.60f,.59f,.53f));ts.SetColor("_BaseColor",new Color(1.06f,1.02f,.96f));stone=ts;EditorUtility.SetDirty(stone);mortar=Lit("Chaux_Joints",new Color(.53f,.50f,.44f));iron=Lit("Fer_Forge",new Color(.20f,.22f,.20f),.65f);
   string wp=Root+"/Materials/Bois_Patine.mat";wood=AssetDatabase.LoadAssetAtPath<Material>(wp);if(!wood){wood=new Material(Shader.Find("CorseVR/Maquis V2 Mineral Botanique"));AssetDatabase.CreateAsset(wood,wp);}wood.SetFloat("_Mode",1);wood.SetFloat("_ColorsAreSRGB",1);wood.SetFloat("_Roughness",.9f);wood.SetColor("_ShadowTint",new Color(.48f,.50f,.45f));var tx=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Prototype_Maquis/Art/MaisonRefonte/Textures/Bois_Miel_Peint.png");wood.SetTexture("_BaseMap",tx);wood.SetTexture("_BarkMap",tx);wood.enableInstancing=true;EditorUtility.SetDirty(wood);
   var body=new GameObject("Tour_Genoise");var lods=new List<LOD>();
   for(int i=0;i<3;i++){var ob=Model("Tour_Genoise_LOD"+i,body.transform);var rs=ob.GetComponentsInChildren<Renderer>();foreach(var r in rs){r.sharedMaterial=r.name.Contains("Joints")?mortar:stone;r.shadowCastingMode=ShadowCastingMode.On;}Record(ob);lods.Add(new LOD(i==0?.30f:i==1?.12f:.008f,rs));}
   var lg=body.AddComponent<LODGroup>();lg.SetLODs(lods.ToArray());lg.RecalculateBounds();var collision=Model("Tour_Collision",body.transform);foreach(var f in collision.GetComponentsInChildren<MeshFilter>()){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;}foreach(var rr in collision.GetComponentsInChildren<Renderer>())UnityEngine.Object.DestroyImmediate(rr);Record(collision);
   var floor=body.AddComponent<BoxCollider>();floor.center=new Vector3(0,.05f,0);floor.size=new Vector3(4.3f,.10f,4.3f);var strip=body.AddComponent<BoxCollider>();strip.center=new Vector3(0,.05f,0);strip.size=new Vector3(1.90f,.10f,7.5f);foreach(int side in new[]{-1,1}){var threshold=body.AddComponent<BoxCollider>();threshold.center=new Vector3(0,.075f,side*3.65f);threshold.size=new Vector3(2.45f,.15f,1.05f);}PrefabUtility.SaveAsPrefabAsset(body,Root+"/Prefabs/Tour_Genoise.prefab");UnityEngine.Object.DestroyImmediate(body);
   var door=new GameObject("Porte_Tour_Genoise");var d=Model("Porte_Tour",door.transform);foreach(var rr in d.GetComponentsInChildren<Renderer>())rr.sharedMaterial=rr.name.Contains("Ferrures")?iron:wood;Record(d);var dc=door.AddComponent<BoxCollider>();dc.center=new Vector3(.90f,1.24f,0);dc.size=new Vector3(1.80f,2.46f,.15f);door.AddComponent<AccueilDoor>();PrefabUtility.SaveAsPrefabAsset(door,Root+"/Prefabs/Porte_Tour.prefab");UnityEngine.Object.DestroyImmediate(door);
   foreach(string file in Directory.GetFiles(Root+"/Models","Fond_*.fbx")){var key=Path.GetFileNameWithoutExtension(file);var go=new GameObject(key);var model=Model(key,go.transform);foreach(var rr in model.GetComponentsInChildren<Renderer>()){rr.sharedMaterial=bot;rr.shadowCastingMode=ShadowCastingMode.Off;rr.lightProbeUsage=LightProbeUsage.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;}Record(model);PrefabUtility.SaveAsPrefabAsset(go,Root+"/Prefabs/"+key+".prefab");UnityEngine.Object.DestroyImmediate(go);}
