  }
  static Mesh SaveMesh(string name,Mesh mesh){mesh.name=name;string path=Root+"/Meshes/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){var vertices=mesh.vertices;var colors=mesh.colors;var uvs=mesh.uv;int count=mesh.subMeshCount;var indices=Enumerable.Range(0,count).Select(i=>mesh.GetTriangles(i)).ToArray();old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=vertices;old.colors=colors;old.uv=uvs;old.subMeshCount=count;for(int i=0;i<count;i++)old.SetTriangles(indices[i],i);old.RecalculateNormals();old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
  static float OldHeight(Vector3 world){var p=main.InverseTransformPoint(world);float x=(p.x+25.2f)/.4f,z=(p.z+18)/.4f;int i=Mathf.Clamp(Mathf.FloorToInt(x),0,135),j=Mathf.Clamp(Mathf.FloorToInt(z),0,175);float xx=Mathf.Clamp01(x-i),zz=Mathf.Clamp01(z-j);float y=Mathf.Lerp(Mathf.Lerp(originalVertices[j*137+i].y,originalVertices[j*137+i+1].y,xx),Mathf.Lerp(originalVertices[(j+1)*137+i].y,originalVertices[(j+1)*137+i+1].y,xx),zz);return main.TransformPoint(new Vector3(p.x,y,p.z)).y;}
  static void NearMain(Vector3 p,out float distance,out float station){float best=float.MaxValue;station=0;for(int i=0;i<route.points.Length;i++){var q=main.TransformPoint(route.points[i]);float d=new Vector2(p.x-q.x,p.z-q.z).sqrMagnitude;if(d<best){best=d;station=route.distances[i];}}distance=Mathf.Sqrt(best);}
  static float CoastY(float z){float t=Mathf.Max(0,z-3.65f);return .10f-.041f*t+.045f*Mathf.Sin(t*.40f);}
  static Vector3 Cat(Vector3 a,Vector3 b,Vector3 c,Vector3 d,float t){return .5f*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);}
  static Vector3[] CoastPath(){var ks=new[]{new Vector3(0,0,3.65f),new Vector3(.1f,0,5.1f),new Vector3(.75f,0,7.5f),new Vector3(1.8f,0,9.7f),new Vector3(1.45f,0,12.2f),new Vector3(2.75f,0,15.0f),new Vector3(4.0f,0,18.2f)};var list=new List<Vector3>();for(int i=0;i<ks.Length-1;i++)for(int j=0;j<20;j++){var p=Cat(ks[Mathf.Max(0,i-1)],ks[i],ks[i+1],ks[Mathf.Min(ks.Length-1,i+2)],j/20f);p.y=CoastY(p.z);list.Add(p);}var end=ks[ks.Length-1];end.y=CoastY(end.z);list.Add(end);return list.ToArray();}
  static float CoastDistance(Vector3 local){float d=float.MaxValue;foreach(var p in coast.coastPoints)d=Mathf.Min(d,new Vector2(p.x-local.x,p.z-local.z).magnitude);return d;}
  static float CoastHeight(float x,float z){if(new Vector2(x,z).magnitude<4.65f || Mathf.Abs(x)<1.25f && z<5.2f)return .10f;float d=CoastDistance(new Vector3(x,0,z));float path=CoastY(z);float bank=Mathf.SmoothStep(0,1,Mathf.Max(0,d-.88f)/3);float h=path+bank*(.45f+1.4f*Mathf.PerlinNoise(x*.16f+3,z*.14f));if(x< -7)h+=Mathf.SmoothStep(0,1,(-x-7)/10)*2.2f;float old=OldHeight(tour.TransformPoint(new Vector3(x,0,z)))-tour.position.y;float blend=Mathf.SmoothStep(0,1,(z-1.6f)/4.3f);if(d>1.4f)h=Mathf.Lerp(old,h,blend);float shore=6.8f+1.6f*Mathf.Sin(z*.11f);h=Mathf.Lerp(h,-8f,Mathf.SmoothStep(0,1,(x-shore)/4.8f));return h;}
  static void Terrain(){
   var mesh=UnityEngine.Object.Instantiate(originalGround.sharedMesh);var vs=mesh.vertices;var cs=mesh.colors;
   for(int i=0;i<vs.Length;i++){var world=main.TransformPoint(vs[i]);var p=tour.InverseTransformPoint(world);float radius=new Vector2(p.x,p.z).magnitude;float d,s;NearMain(world,out d,out s);bool protectedPath=d<1.12f&&s<34.85f;
    if(!protectedPath&&radius<6.0f){float t=1-Mathf.SmoothStep(0,1,(radius-4.4f)/1.6f);world.y=Mathf.Lerp(world.y,tour.position.y+.025f,t);}
    if(p.z>2.2f)world.y=tour.position.y-9;
    vs[i]=main.InverseTransformPoint(world);if(radius<4.1f&&p.z< -2.7f)cs[i]=new Color(1,.5f,.5f,1);
   }mesh.vertices=vs;mesh.colors=cs;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=SaveMesh("Sol_Maquis_Raccord_Tour",mesh);originalGround.sharedMesh=mesh;originalGround.GetComponent<MeshFilter>().sharedMesh=mesh;
   const int nx=73,nz=72;var cvs=new Vector3[nx*nz];var colors=new Color[cvs.Length];var uv=new Vector2[cvs.Length];var land=new List<int>();var cliff=new List<int>();
   for(int j=0;j<nz;j++)for(int i=0;i<nx;i++){float x=-22+i*.60f,z=1.6f+j*.60f;int k=j*nx+i;cvs[k]=new Vector3(x,CoastHeight(x,z),z);float d=CoastDistance(cvs[k]);colors[k]=new Color(1-Mathf.SmoothStep(0,1,(d-.65f)/.65f),.5f,.5f,1);uv[k]=new Vector2(x,z);if(i<nx-1&&j<nz-1){float shore=6.8f+1.6f*Mathf.Sin((z+.3f)*.11f);var list=x+.3f>shore-.2f?cliff:land;if(new Vector2(x+.3f,z+.3f).magnitude<3.8f)continue;list.AddRange(new[]{k,k+nx,k+1,k+1,k+nx,k+nx+1});}}
   foreach(bool rock in new[]{false,true}){var m=new Mesh();m.vertices=cvs;m.uv=uv;m.colors=rock?cvs.Select(v=>new Color(.68f,.65f,.57f,1)).ToArray():colors;m.triangles=(rock?cliff:land).ToArray();m.RecalculateNormals();m.RecalculateBounds();m=SaveMesh(rock?"Falaises_Littoral":"Terrain_Littoral",m);var go=new GameObject(rock?"Falaises_Granitiques":"Sol_Chemin_Littoral");go.transform.SetParent(tour.Find("02_Terrain_Littoral"),false);go.AddComponent<MeshFilter>().sharedMesh=m;var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=rock?stone:(AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Terre_Littorale.mat")??earth);rr.shadowCastingMode=ShadowCastingMode.Off;var c=go.AddComponent<MeshCollider>();c.sharedMesh=m;if(!rock)coastGround=c;}
   // Rock skirts close the finite terrain surface below the visible ridge, into the sea.
   var sv=new List<Vector3>();var st=new List<int>();Action<Vector3,Vector3> edge=(a,b)=>{if(Mathf.Max(a.y,b.y)<tour.position.y-7.9f)return;int k=sv.Count;sv.Add(a);sv.Add(b);sv.Add(new Vector3(b.x,tour.position.y-8.3f,b.z));sv.Add(new Vector3(a.x,tour.position.y-8.3f,a.z));st.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});};
   for(int j=0;j<176;j++){edge(main.TransformPoint(vs[j*137]),main.TransformPoint(vs[(j+1)*137]));edge(main.TransformPoint(vs[j*137+136]),main.TransformPoint(vs[(j+1)*137+136]));}for(int i=0;i<136;i++){edge(main.TransformPoint(vs[i]),main.TransformPoint(vs[i+1]));edge(main.TransformPoint(vs[176*137+i]),main.TransformPoint(vs[176*137+i+1]));}
   for(int j=0;j<nz-1;j++){edge(tour.TransformPoint(cvs[j*nx]),tour.TransformPoint(cvs[(j+1)*nx]));edge(tour.TransformPoint(cvs[j*nx+nx-1]),tour.TransformPoint(cvs[(j+1)*nx+nx-1]));}for(int i=0;i<nx-1;i++)edge(tour.TransformPoint(cvs[(nz-1)*nx+i]),tour.TransformPoint(cvs[(nz-1)*nx+i+1]));
   var skirt=new Mesh();skirt.SetVertices(sv);skirt.SetTriangles(st,0);skirt.colors=sv.Select(v=>new Color(.58f,.59f,.54f,1)).ToArray();skirt.uv=sv.Select(v=>new Vector2(v.x,v.y)).ToArray();skirt.RecalculateNormals();skirt.RecalculateBounds();skirt=SaveMesh("Enveloppe_Rocheuse_Sous_Terrain",skirt);var sk=new GameObject("Enveloppe_Rocheuse");sk.AddComponent<MeshFilter>().sharedMesh=skirt;sk.AddComponent<MeshRenderer>().sharedMaterial=stone;sk.transform.SetParent(tour.Find("02_Terrain_Littoral"),true);
  }
  static bool Ground(Vector3 at,out Vector3 point){RaycastHit a,b;bool aa=originalGround.Raycast(new Ray(at+Vector3.up*60,Vector3.down),out a,150),bb=coastGround.Raycast(new Ray(at+Vector3.up*60,Vector3.down),out b,150);point=bb&&(!aa||b.point.y>a.point.y)?b.point:aa?a.point:at;return aa||bb;}
  static GameObject Plant(string species,int variant,Vector3 world,float height,Transform parent,bool far){string path;if(far)path=Root+"/Prefabs/Fond_"+species+"_"+(variant%2)+".prefab";else{var keys=Directory.GetFiles(V2+"/Prefabs",species+"_*.prefab").OrderBy(s=>s).ToArray();path=keys[variant%keys.Length].Replace('\\','/');}var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab)throw new Exception(path);var ob=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);ob.transform.position=world-Vector3.up*.035f;ob.transform.rotation=Quaternion.Euler(0,R(0,360),0);float h=ob.GetComponentsInChildren<Renderer>().First().bounds.size.y;ob.transform.localScale=Vector3.one*height/Mathf.Max(.05f,h);if(!far){foreach(var rr in ob.GetComponentsInChildren<Renderer>())if(height<.8f)rr.shadowCastingMode=ShadowCastingMode.Off;Record(ob);}else farObjects.Add(ob);placements.Add(new{species,variant,position=world.ToString("F4"),height,background=far});return ob;}
  static void BatchFar(Transform parent){foreach(var cell in farObjects.GroupBy(g=>Mathf.FloorToInt(g.transform.position.x/8)+"_"+Mathf.FloorToInt(g.transform.position.z/8))){var instances=cell.SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=parent.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var m=new Mesh();m.indexFormat=IndexFormat.UInt32;m.CombineMeshes(instances,true,true);m.RecalculateBounds();m=SaveMesh("Fond_Compose_"+cell.Key,m);var go=new GameObject("Fond_Compose_"+cell.Key);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=m;var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=bot;rr.shadowCastingMode=ShadowCastingMode.Off;rr.lightProbeUsage=LightProbeUsage.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;}foreach(var go in farObjects)UnityEngine.Object.DestroyImmediate(go);farObjects.Clear();}
  static void Vegetation(){
   var near=main.Find("11_Densification/Proche");var far=main.Find("11_Densification/Fonds_Groupes");int moved=0,disabled=0;
   // Preserve the library and relocate only instances now occupying the tower and its exit.
   foreach(var group in main.Find("10_Refonte_Botanique_V2").GetComponentsInChildren<LODGroup>()){
    var p=tour.InverseTransformPoint(group.transform.position);if(new Vector2(p.x,p.z).magnitude>5.0f&&!(p.z>2.0f&&p.z<22&&CoastDistance(p)<1.55f))continue;float a=R(0,Mathf.PI*2);var q=tour.TransformPoint(new Vector3(Mathf.Cos(a)*R(6,8.4f),0,Mathf.Sin(a)*R(6,8.4f)));float d,s;NearMain(q,out d,out s);if(d<1.65f)q+=tour.right*4;Vector3 ground;if(Ground(q,out ground)){group.transform.position=ground-Vector3.up*.05f;PrefabUtility.RecordPrefabInstancePropertyModifications(group.transform);moved++;}
   }
   foreach(var c in main.Find("08_Collisions_Parcours").GetComponentsInChildren<Collider>()){var p=tour.InverseTransformPoint(c.bounds.center);if(new Vector2(p.x,p.z).magnitude<4.8f&&p.z> -3.1f){c.enabled=false;disabled++;}}
   foreach(Transform rock in main.Find("10_Refonte_Botanique_V2/E_Roches")){var p=tour.InverseTransformPoint(rock.position);if(new Vector2(p.x,p.z).magnitude<5.0f||p.z>2.2f){var q=tour.TransformPoint(new Vector3(R(-6,-3.4f),0,R(5,22)));Vector3 hit;if(Ground(q,out hit)){rock.position=hit-Vector3.up*.16f;PrefabUtility.RecordPrefabInstancePropertyModifications(rock);}}}
   int idx=0;for(float z=-17;z<52;z+=1.8f)for(float x=-24.5f;x<29;x+=1.8f){var local=new Vector3(x+R(-.65f,.65f),0,z+R(-.65f,.65f));if(local.x> -5.1f&&local.x<5.1f&&local.z> -8&&local.z<1.7f)continue;var world=main.TransformPoint(local);var tp=tour.InverseTransformPoint(world);if(tp.z>1.6f||new Vector2(tp.x,tp.z).magnitude<5.1f)continue;float d,s;NearMain(world,out d,out s);if(d<1.4f)continue;Vector3 point;if(!Ground(world,out point)||point.y<tour.position.y-5)continue;
    float patch=Mathf.PerlinNoise(local.x*.13f+9,local.z*.12f+3);string species=patch<.24f?"Bruyere":patch<.44f?"Lentisque":patch<.65f?"Ciste":patch<.83f?"Myrte":"Arbousier";bool distant=d>5.4f;float h=species=="Ciste"?R(.45f,.85f):species=="Arbousier"||species=="Bruyere"?R(1.4f,2.7f):R(.85f,1.65f);Plant(species,idx++,point,h,distant?far:near,distant);
    if(idx%2==0){var p=point+new Vector3(R(-.7f,.7f),0,R(-.7f,.7f));if(Ground(p,out p))Plant("Herbes",idx,p,R(.20f,.36f),far,true);}
   }
   // Scattered high crowns, with varied distance and side, complete the background depth.
   for(float s=3;s<35;s+=R(3.0f,5.4f)){var d=route.Direction(s);var n=Vector3.Cross(Vector3.up,d).normalized;var p=route.WorldAt(s)+n*(rng.Next(2)==0?-1:1)*R(5.3f,8.1f);Vector3 hit;if(Ground(p,out hit)&&new Vector2(tour.InverseTransformPoint(p).x,tour.InverseTransformPoint(p).z).magnitude>5.4f)Plant("CheneVert",idx++,hit,R(5.4f,7.4f),near,false);}
   var coastal=tour.Find("03_Vegetation_Littorale");for(float z=2.5f;z<40;z+=1.65f)for(float x=-19;x<9;x+=1.65f){var p=new Vector3(x+R(-.58f,.58f),0,z+R(-.58f,.58f));float d=CoastDistance(p);if(d<1.35f||new Vector2(p.x,p.z).magnitude<4.9f||p.x>6.3f+1.6f*Mathf.Sin(p.z*.11f))continue;var world=tour.TransformPoint(p);Vector3 hit;if(!Ground(world,out hit))continue;float patch=Mathf.PerlinNoise(x*.14f+8,z*.2f);string sp=patch<.28f?"Immortelle":patch<.53f?"Lentisque":patch<.74f?"Ciste":"Herbes";float h=sp=="Lentisque"?R(.60f,1.35f):sp=="Ciste"?R(.40f,.70f):R(.20f,.45f);bool distant=d>4.5f;Plant(sp,idx++,hit,h,distant?far:coastal,distant);}
   // Tower base remains vegetated outside the arrival, passage and foundation.
   for(int i=0;i<40;i++){float a=R(0,Mathf.PI*2),radius=R(4.6f,7.8f);var p=new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius);if(Mathf.Abs(p.x)<1.8f)continue;Vector3 world=tour.TransformPoint(p),hit;float d,s;NearMain(world,out d,out s);if(d<1.6f||CoastDistance(p)<1.5f||!Ground(world,out hit))continue;string sp=i%3==0?"Immortelle":i%2==0?"Lentisque":"Ciste";Plant(sp,i,hit,sp=="Lentisque"?R(.8f,1.4f):R(.3f,.65f),coastal,false);}
   BatchFar(far);Debug.Log("TourLittoral: preserved plants relocated="+moved+", obsolete backdrop colliders superseded="+disabled+", new vegetation placements="+placements.Count);
  }
  static void CoastRocks(){var parent=tour.Find("04_Rochers_Littoral");for(int i=0;i<45;i++){float z=R(4.9f,39),x=i<28?R(5.0f,9.0f):R(-7,-2.6f);var p=new Vector3(x,0,z);if(CoastDistance(p)<1.6f)continue;var world=tour.TransformPoint(new Vector3(x,CoastHeight(x,z),z));int v=i%4;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(V2+"/Prefabs/Granit_V2_"+v+".prefab");var ob=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);ob.transform.SetPositionAndRotation(world-Vector3.up*R(.25f,.65f),Quaternion.Euler(R(-12,12),R(0,360),R(-12,12)));ob.transform.localScale=Vector3.one*R(.65f,1.4f);foreach(var rr in ob.GetComponentsInChildren<Renderer>())rr.shadowCastingMode=ShadowCastingMode.Off;Record(ob);}}
  static void Sea(){var m=new Material(Shader.Find("CorseVR/Mer Littorale Opaque"));m.name="Mer_Mediterraneenne";m.SetVector("_Origin",tour.position);m.SetVector("_Right",tour.right);m.SetVector("_Forward",tour.forward);AssetDatabase.CreateAsset(m,Root+"/Materials/Mer_Mediterraneenne.mat");var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-1000,-8,-1000),new Vector3(1000,-8,-1000),new Vector3(1000,-8,1000),new Vector3(-1000,-8,1000)};mesh.triangles=new[]{0,2,1,0,3,2};mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=SaveMesh("Mer_Plan_Opaque",mesh);var go=new GameObject("Mer_Mediterranee");go.transform.SetParent(tour.Find("05_Mer_Horizon"),false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=m;rr.shadowCastingMode=ShadowCastingMode.Off;Camera.main.farClipPlane=900;}
  static void Corridor(){var player=GameObject.Find("Joueur_Desktop");var corridor=player.GetComponent<SentierCorridor>();var old=corridor.CentreLine;var so=new SerializedObject(corridor);var arr=so.FindProperty("sectionHalfWidths");var widths=new List<float>();for(int i=0;i<old.Length;i++)widths.Add(arr!=null&&arr.arraySize==old.Length?arr.GetArrayElementAtIndex(i).floatValue:corridor.HalfWidth);var line=old.ToList();for(float z=-3.45f;z<3.65f;z+=.20f){line.Add(tour.TransformPoint(new Vector3(0,.10f,z)));widths.Add(Mathf.Abs(z)>1.6f?.59f:1.1f);}foreach(var p in coast.coastPoints){line.Add(tour.TransformPoint(p));widths.Add(.58f);}corridor.Configure(line.ToArray(),.58f);corridor.ConfigureWidths(widths.ToArray());EditorUtility.SetDirty(corridor);}
  public static string Build(){
   if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(GameObject.Find("Extension_Tour_Littoral"))throw new Exception("Already installed; edit the current scene, do not regenerate");if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Prototype_Maquis")throw new Exception("Wrong scene");
