   var body=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/Tour_Genoise.prefab"),tour.Find("01_Tour_Genoise"));body.transform.localPosition=Vector3.zero;var door=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/Porte_Tour.prefab"),body.transform);door.transform.localPosition=new Vector3(-.90f,.145f,-3.62f);door.GetComponent<AccueilDoor>().Configure(Camera.main.transform);Record(door);coast.entranceDoor=door.transform;
