  public static string RefineInstalled(){
   if(EditorApplication.isPlaying)throw new Exception("Edit mode required");rng=new System.Random(471025);main=GameObject.Find("Maquis_35m").transform;route=main.GetComponent<Maquis35Route>();tour=GameObject.Find("Extension_Tour_Littoral").transform;coast=tour.GetComponent<TourLittoralRoute>();bot=AssetMat("Botanique_Fibres_Nervures");stone=AssetMat("Granit_Quartz_Mica");earth=AssetMat("Terre_Graviers");originalGround=main.Find("01_Terrain_Chemin").GetComponentInChildren<MeshCollider>();var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Prototype_Maquis/Art/Maquis35/Meshes/Terrain_Sentier_Continu.asset");originalVertices=original.vertices;originalGround.sharedMesh=original;originalGround.GetComponent<MeshFilter>().sharedMesh=original;
   foreach(Transform child in tour.Find("02_Terrain_Littoral").Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);Terrain();int moved=0;
   foreach(var group in main.Find("10_Refonte_Botanique_V2").GetComponentsInChildren<LODGroup>()){
    var p=tour.InverseTransformPoint(group.transform.position);Vector3 hit;
    if(p.z>1.6f){var local=new Vector3(rng.Next(2)==0?R(-23,-7):R(11,26),0,R(1.8f,28));var world=main.TransformPoint(local);if(Ground(world,out hit)){group.transform.position=hit-Vector3.up*.05f;Record(group.gameObject);moved++;}}
    else if(Ground(group.transform.position,out hit)){group.transform.position=hit-Vector3.up*.05f;PrefabUtility.RecordPrefabInstancePropertyModifications(group.transform);}
   }
   foreach(var group in tour.Find("03_Vegetation_Littorale").GetComponentsInChildren<LODGroup>()){Vector3 hit;if(Ground(group.transform.position,out hit)){group.transform.position=hit-Vector3.up*.035f;PrefabUtility.RecordPrefabInstancePropertyModifications(group.transform);}}
   foreach(Transform rock in tour.Find("04_Rochers_Littoral")){var p=tour.InverseTransformPoint(rock.position);if(p.x>4.8f&&p.z>8&&p.z<22){rock.localScale=Vector3.Scale(rock.localScale,new Vector3(.85f,.42f,.95f));rock.position-=Vector3.up*.20f;Record(rock.gameObject);}}
   // A low understory closes the bare banks below the taller crowns, leaving the tread clear.
   var low=main.Find("11_Densification").Find("Strate_Basse_Talus");int added=0;if(!low){low=Group("Strate_Basse_Talus",main.Find("11_Densification"));for(float s=2.5f;s<34;s+=R(.9f,1.4f))for(int side=-1;side<=1;side+=2){var normal=Vector3.Cross(Vector3.up,route.Direction(s)).normalized;var p=route.WorldAt(s)+normal*side*R(2.0f,3.5f);Vector3 hit;if(new Vector2(tour.InverseTransformPoint(p).x,tour.InverseTransformPoint(p).z).magnitude<5.2f||!Ground(p,out hit))continue;Plant(s>13&&s<22?"Myrte":"Ciste",added++,hit,R(.68f,1.05f),low,false);}}
   // Embed rocks using the lowest terrain sample under their footprint.
   var terrainColliders=tour.Find("02_Terrain_Littoral").GetComponentsInChildren<MeshCollider>().Concat(new[]{originalGround}).ToArray();int embedded=0;
   foreach(var parent in new[]{tour.Find("04_Rochers_Littoral"),main.Find("10_Refonte_Botanique_V2/E_Roches")})foreach(Transform ob in parent){var rr=ob.GetComponentInChildren<Renderer>();if(!rr)continue;var b=rr.bounds;float min=999;for(int xx=-1;xx<=1;xx++)for(int zz=-1;zz<=1;zz++){var ray=new Ray(new Vector3(b.center.x+xx*b.extents.x*.75f,50,b.center.z+zz*b.extents.z*.75f),Vector3.down);float highest=-999;foreach(var collider in terrainColliders){RaycastHit hit;if(collider.Raycast(ray,out hit,150))highest=Mathf.Max(highest,hit.point.y);}if(highest> -998)min=Mathf.Min(min,highest);}if(min<998){float delta=Mathf.Min(0,min-.08f-b.min.y);if(delta<-.001f){ob.position+=Vector3.up*delta;PrefabUtility.RecordPrefabInstancePropertyModifications(ob);embedded++;}}}
   Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Terrain under chamber removed; original coastal trees grounded/relocated="+moved+"; understory added="+added+"; rock contacts adjusted="+embedded;
  }
